import com.android.apksig.ApkVerifier;import java.io.File;import java.security.MessageDigest;
public class VerifyApk {public static void main(String[] args)throws Exception {String first=null;for(String arg:args){ApkVerifier.Result r=new ApkVerifier.Builder(new File(arg)).build().verify();if(!r.isVerified()||!r.isVerifiedUsingV2Scheme()||!r.isVerifiedUsingV3Scheme())throw new AssertionError(r.getErrors().toString());byte[] hash=MessageDigest.getInstance("SHA-256").digest(r.getSignerCertificates().get(0).getEncoded());StringBuilder s=new StringBuilder();for(byte b:hash)s.append(String.format("%02x",b&255));if(first==null)first=s.toString();else if(!first.equals(s.toString()))throw new AssertionError("Signer differs");System.out.println(arg+" v2/v3 PASS certificate SHA256 "+s);}}}
